import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_linear_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int batch_size,
    int in_features,
    int out_features,
    float scale
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < batch_size && col < out_features) {
        float val = 0.0f;
        for (int i = 0; i < in_features; i++) {
            val += x[row * in_features + i] * w[col * in_features + i];
        }
        val += b[col];
        val *= (1.0f + scale);
        out[row * out_features + col] = val;
    }
}

torch::Tensor fused_linear_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    float scale
) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = w.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());
    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x, (out_features + block.y - 1) / block.y);

    fused_linear_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        scale
    );

    return out;
}
"""

fused_linear_cpp_source = r"""
torch::Tensor fused_linear_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b, float scale);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_linear_cpp_source,
    cuda_sources=fused_linear_source,
    functions=["fused_linear_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.scaling_factor = scaling_factor

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_ops.fused_linear_cuda(x, self.weight, self.bias, self.scaling_factor)
